import itertools, random, sys, time

def has_short_cycle(edges, max_len=6):
    """Check if graph has any cycle of length <= max_len"""
    n = max(max(u,v) for u,v in edges) + 1 if edges else 0
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex to detect short cycles
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        stack = [s]
        while stack:
            u = stack.pop()
            for w in adj[u]:
                if dist[w] == -1:
                    dist[w] = dist[u] + 1
                    parent[w] = u
                    stack.append(w)
                elif w != parent[u] and dist[w] + dist[u] + 1 <= max_len:
                    # cycle found
                    return True
    return False

def is_4_colorable(edges):
    """Check if graph is 4-colorable using brute force (small graph)"""
    n = max(max(u,v) for u,v in edges) + 1 if edges else 0
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Try all 4^n colorings (n=20, 4^20 is too large)
    # Use backtracking
    colors = [-1]*n
    def dfs(v):
        if v == n:
            return True
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(4):
            if c not in used:
                colors[v] = c
                if dfs(v+1):
                    return True
                colors[v] = -1
        return False
    return dfs(0)

