import random

n = 20
target = 37

def has_short_cycle(edges, u, v, max_path_len=5):
    """Check if adding edge (u,v) creates a cycle of length <= max_path_len+1"""
    adj = {i: set() for i in range(n)}
    for a,b in edges:
        adj[a].add(b)
        adj[b].add(a)

    # BFS from u to v, limit depth to max_path_len
    visited = {u}
    queue = [(u, 0)]
    while queue:
        node, dist = queue.pop(0)
        if node == v and dist > 0:
            if dist + 1 <= max_path_len + 1:
                return True
            continue
        if dist >= max_path_len:
            continue
        for nb in adj[node]:
            if nb not in visited:
                visited.add(nb)
                queue.append((nb, dist+1))
    return False

